<?php
defined( 'ABSPATH' ) || exit;

/**
 * "آموزش": a short, static, Persian how-to inside the plugin (no data is read or changed here).
 * Every statement describes what the code does today; the variable list comes from CRDR_UI::variable_catalog().
 */
class CRDR_Page_Guide {

	public static function render() {
		CRDR_UI::open( 'آموزش', 'customer-radar-guide', 'یاد بگیرید در چند دقیقه از رادار مشتری استفاده کنید؛ هر بخش را باز کنید.' );
		$link = function ( $slug, $label ) {
			return '<a href="' . esc_url( admin_url( 'admin.php?page=' . $slug ) ) . '">' . esc_html( $label ) . '</a>';
		};

		self::section( 'شروع سریع (۵ قدم)', true, function () use ( $link ) {
			echo '<ol class="crdr-steps">';
			echo '<li>در ' . $link( 'customer-radar', 'داشبورد' ) . ' دکمه‌ی <strong>«تحلیل سفارش‌ها»</strong> را بزنید و صبر کنید تا بنویسد «انجام شد». (بخش «تحلیل سفارش‌ها» را ببینید.)</li>'; // phpcs:ignore WordPress.Security.EscapeOutput
			echo '<li>در ' . $link( 'customer-radar-settings', 'تنظیمات' ) . ' بخش «کدام سفارش‌ها شمرده شوند؟» را نگاه کنید (معمولاً «تکمیل‌شده» و «در حال انجام»).</li>'; // phpcs:ignore WordPress.Security.EscapeOutput
			echo '<li>همان‌جا سرویس پیامک را انتخاب کنید: افزونه‌ی «پیامک ووکامرس»، یا کاوه‌نگار با کلید API و شماره‌ی خط اختصاصی خودتان.</li>';
			echo '<li>به ' . $link( 'customer-radar-calls', 'فهرست تماس' ) . ' بروید: کسانی که موعد خریدشان رسیده‌اند را می‌بینید. می‌توانید تماس بگیرید و «تماس گرفتم» را بزنید، یا برای هر نفر پیامک بفرستید.</li>'; // phpcs:ignore WordPress.Security.EscapeOutput
			echo '<li>برای ارسال گروهی، از ' . $link( 'customer-radar-campaigns', 'کمپین‌ها' ) . ' یکی را باز کنید، «پیش‌نمایش و اجرا» را بزنید، نمونه پیام‌ها را بخوانید و فقط بعد اجرا کنید.</li>'; // phpcs:ignore WordPress.Security.EscapeOutput
			echo '</ol><p class="crdr-muted">هیچ کمپینی تا وقتی خودتان «دستی» یا «خودکار» نکنید پیامک نمی‌فرستد. برای اولین بار سقف ارسال در روز را کم بگذارید (مثلاً ۱۰).</p>';
		} );

		self::section( 'تحلیل مشتریان و RFM', false, function () {
			echo '<p>RFM یعنی برای هر مشتری سه چیز را بسنجیم: <strong>R</strong> = چند وقت پیش خرید کرده (تازگی)، <strong>F</strong> = چند بار خرید کرده، <strong>M</strong> = چقدر خرج کرده. هر کدام امتیاز ۱ تا ۵ می‌گیرد؛ <strong>عدد بیشتر بهتر است</strong>. مثال: «۵ / ۴ / ۵» یعنی تازه خرید کرده، چند بار خریده و پرخرج است.</p>';
			echo '<p>از روی این سه عدد هر مشتری در یکی از ۹ گروه قرار می‌گیرد:</p><dl class="crdr-vars">';
			$hints = CRDR_RFM::segment_hints();
			foreach ( CRDR_RFM::segments() as $k => $label ) {
				echo '<dt>' . CRDR_UI::badge( $k ) . '</dt><dd>' . esc_html( $hints[ $k ] ) . '</dd>'; // phpcs:ignore WordPress.Security.EscapeOutput
			}
			echo '</dl><p><strong>فهرست تماس امروز:</strong> مشتریانی که «روز از آخرین خرید ÷ فاصله‌ی معمول خرید خودشان» به عدد تنظیمات (پیش‌فرض ۰٫۹) رسیده است. مثال: کسی که معمولاً هر ۶۰ روز می‌خرد، از روز ۵۴ در فهرست می‌آید. «اولویت» فقط یک فرمول ترتیب‌دهی است (میانگین سبد × ضریب زمان‌بندی × وزن گروه)، نه پیش‌بینی خرید.</p>';
			echo '<p><strong>«فروش» در این افزونه فروش خالص است:</strong> مبلغ کالاها منهای مرجوعی؛ بدون هزینه‌ی ارسال، مالیات و هزینه‌های جانبی (مثل «پرداخت در محل»).</p>';
		} );

		self::section( 'محصولات مکمل', false, function () use ( $link ) {
			echo '<p>در ' . $link( 'customer-radar-products', 'محصولات و مکمل' ) . ' می‌بینید کدام دو محصول با هم خریده می‌شوند (مثلاً سرم ویتامین سی + ضدآفتاب). «لیفت ۳×» یعنی این دو سه برابرِ حالت تصادفی با هم خریده شده‌اند.</p>'; // phpcs:ignore WordPress.Security.EscapeOutput
			echo '<ol class="crdr-steps"><li><strong>پیشنهاد با پیامک:</strong> کمپین «پیشنهاد محصول مکمل» برای هر مشتری، محصولی را انتخاب می‌کند که خریداران خریدهای او معمولاً می‌خرند و خودش هنوز نخریده است (فقط محصول منتشرشده، قابل خرید و موجود). در متن می‌توانید <code>{product}</code> و <code>{bought}</code> بنویسید. اگر برای کسی محصول مناسبی نباشد، پیامی برایش نمی‌رود.</li>';
			echo '<li><strong>بسته با تخفیف:</strong> دکمه‌ی «ساخت کد تخفیف بسته» یک کد واقعی در ووکامرس می‌سازد (۳۰ روز، فقط روی آن دو محصول). این کد یک‌بارمصرف نیست؛ هر کس آن را داشته باشد استفاده می‌کند. پیش از ساختن، ستون «شرط صرفه» را بخوانید: اگر تخفیف از حاشیه‌ی سود بیشتر باشد بسته زیان‌ده است.</li></ol>';
			echo '<p class="crdr-muted">اگر جدول خالی است، هنوز جفت محصول معناداری پیدا نشده؛ سفارش‌های بیشتری لازم است.</p>';
		} );

		self::section( 'نوشتن متن پیامک', false, function () {
			echo '<p>متن را مثل یک پیام عادی بنویسید و جای نام و کد را با متغیر پر کنید. مثال:</p><p class="crdr-sample">سلام {name} عزیز، برای شما در {store} کد تخفیف {discount}٪ با کد {coupon} فعال کردیم (تا {expire}). {optout}</p>';
			echo '<p>مشتری این را می‌بیند: «سلام علی عزیز، برای شما در فروشگاه نمونه کد تخفیف ۱۰٪ با کد RD7K2M9Q فعال کردیم (تا ۱۴۰۵/۰۸/۰۳). لغو۱۱»</p>';
			echo '<dl class="crdr-vars">';
			foreach ( CRDR_UI::variable_catalog() as $n => $d ) {
				echo '<dt><code>{' . esc_html( $n ) . '}</code></dt><dd>' . esc_html( $d[0] ) . '</dd>';
			}
			echo '</dl><ul class="crdr-steps"><li>هر پیامک تبلیغاتی باید <code>{optout}</code> داشته باشد؛ بدون آن ارسال نمی‌شود.</li><li>متغیرها فقط به همین شکل کار می‌کنند. اگر چیزی را غلط بنویسید، متن ذخیره یا ارسال نمی‌شود و علتش را می‌نویسد.</li><li>حداکثر طول متن ۴۰۰ نویسه است؛ هر ۷۰ نویسه یک بخش پیامک حساب می‌شود و پس از آن هر ۶۷ نویسه یک بخش.</li><li>لینک در پیامک را فقط اگر سرویس پیامک شما اجازه می‌دهد بگذارید.</li></ul>';
		} );

		self::section( 'کمپین‌ها', false, function () use ( $link ) {
			echo '<p>در ' . $link( 'customer-radar-campaigns', 'کمپین‌ها' ) . ' چند کمپین آماده هست (خرید دوم، یادآوری موعد خرید، بازگشت مشتری در خطر، بیدارکردن خواب‌رفته‌ها و…). هر کدام یعنی «به چه کسانی، چه پیامی، با چه پیشنهادی».</p>'; // phpcs:ignore WordPress.Security.EscapeOutput
			echo '<ul class="crdr-steps"><li><strong>غیرفعال / دستی / خودکار:</strong> «دستی» فقط با دکمه‌ی خودتان؛ «خودکار» یعنی افزونه هر ساعت و فقط در ساعت مجاز تنظیمات (پیش‌فرض ۹ تا ۲۱) تا سقف روزانه پیامک واقعی می‌فرستد. هنگام تغییر حالت، توضیح می‌دهد چه می‌شود.</li>';
			echo '<li><strong>پیش‌نمایش:</strong> تعداد مخاطب و چند نمونه‌ی واقعی را نشان می‌دهد. «سناریوی فروش اضافه» یک فرض است، نه پیش‌بینی.</li>';
			echo '<li><strong>گروه شاهد:</strong> درصدی از مخاطبان عمداً پیام نمی‌گیرند تا اثر واقعی کمپین را بسنجید. در «نتایج» «انتخاب‌شده برای پیام» با «گروه شاهد» مقایسه می‌شود.</li>';
			echo '<li><strong>سقف روزانه و فاصله تا پیام بعدی:</strong> برای اینکه یک مشتری زیاد پیام نگیرد.</li>';
			echo '<li><strong>«پذیرفته‌شده» ≠ «رسیده»:</strong> یعنی سرویس پیامک درخواست را پذیرفته. رسیدن به گوشی را افزونه نمی‌داند. «نتیجه نامشخص» (مثلاً قطع ارتباط) عمداً دوباره ارسال نمی‌شود تا پیام تکراری نرود.</li></ul>';
		} );

		self::section( 'تحلیل سفارش‌ها (همگام‌سازی)', false, function () {
			echo '<p>افزونه از روی سفارش‌های ووکامرس جدول‌های خودش را می‌سازد؛ به سفارش‌ها دست نمی‌زند. این کار هر شب ساعت ۳ بامداد انجام می‌شود و با دکمه‌ی «تحلیل سفارش‌ها» در داشبورد هم می‌توانید همین حالا انجام دهید (برای حدود ۳٬۰۰۰ سفارش در آزمایش ما حدود یک تا دو دقیقه).</p><ul class="crdr-steps"><li>در این مدت ارسال پیامک موقتاً متوقف است؛ صفحه را نبندید.</li><li>بعد از تغییر «کدام سفارش‌ها شمرده شوند» در تنظیمات، یک‌بار آن را بزنید.</li><li>بعد از به‌روزرسانی از نسخه‌ی ۱٫۰٫۰ هم یک‌بار لازم است؛ تا آن موقع ارسال پیامک متوقف می‌ماند.</li></ul>';
		} );

		self::section( 'پشتیبان‌گیری و بازگردانی', false, function () {
			echo '<ul class="crdr-steps"><li>از <strong>پایگاه‌داده</strong> پشتیبان بگیرید، نه فقط از پوشه‌ی افزونه. فهرست «پیام نده» و سابقه‌ی پیامک‌ها فقط آنجاست.</li><li><strong>خطر:</strong> اگر پشتیبانِ قدیمی‌تری را بازگردانید، کسانی که بعد از تاریخ آن پشتیبان «پیام نده» شده‌اند دوباره پیامک می‌گیرند؛ افزونه نمی‌تواند این را تشخیص دهد.</li><li>پیش از بازگردانی از «مشتریان» خروجی اکسل بگیرید (ستون آخر «پیام نده»‌ها را نشان می‌دهد). بعد از بازگردانی آن‌ها را دوباره «پیام نده» کنید، تا آن موقع کمپین‌های خودکار را غیرفعال نگه دارید و «تحلیل سفارش‌ها» را بزنید.</li><li><strong>سایت آزمایشی یا کپی:</strong> اگر نشانی سایت با نشانی ثبت‌شده فرق کند، کمپین خودکار متوقف می‌شود و فقط مدیر سایت با تأیید می‌تواند دستی ارسال کند. در سایت آزمایشی کلید API پیامک را حتماً عوض یا خالی کنید.</li></ul>';
		} );

		self::section( 'حریم خصوصی و «پیام نده»', false, function () {
			echo '<ul class="crdr-steps"><li><strong>پیام نده:</strong> مشتری را برای همیشه از پیامک کنار می‌گذارد و از داخل افزونه قابل برگشت نیست. افزونه پاسخ‌های مشتریان (مثل «لغو۱۱») را نمی‌بیند؛ اگر سرویس پیامک شما لغوی را اعلام کرد، خودتان «پیام نده» را بزنید.</li><li>اگر با «پیامک ووکامرس» می‌فرستید، آن افزونه شماره و متن هر پیامک را در بایگانی خودش نگه می‌دارد و رادار مشتری آن را کنترل نمی‌کند.</li><li>ردیف سابقه‌ی مشتریانی که دیگر در سفارش‌ها نیستند ممکن است شماره‌ی موبایل را نگه دارد.</li><li>خروجی اکسل حداکثر ۵۰٬۰۰۰ مشتری است و «پیام نده»‌ها را هم دارد (علامت‌دار)؛ پیش از استفاده در پنل پیامک حذفشان کنید.</li><li>متن پیشنهادی سیاست حریم خصوصی در «تنظیمات ← حریم خصوصی» وردپرس هست.</li></ul>';
		} );

		echo '<p class="crdr-muted">' . esc_html( 'این صفحه فقط توضیح می‌دهد و چیزی را تغییر نمی‌دهد. توضیح مهمِ هر کار، پیش از خودِ کار هم در همان صفحه نوشته شده است.' ) . '</p>';
		CRDR_UI::close();
	}

	private static function section( $title, $open, callable $body ) {
		echo '<details class="crdr-card crdr-guide"' . ( $open ? ' open' : '' ) . '><summary>' . esc_html( $title ) . '</summary><div class="crdr-guide-body">';
		$body();
		echo '</div></details>';
	}
}
